INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Euklidische Algorithmus nur für positive Zahlen geeignet?', 2, '[{"text": "Ja", "correct": true, "because": "Standardanwendung"}, {"text": "Nein", "correct": false, "because": "Erweiterung für negative möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt der Euklidische Algorithmus?', 3, '[{"text": "Größten gemeinsamen Teiler finden", "correct": true, "because": "GGT-Berechnung"}, {"text": "Kleinste Zahl teilen", "correct": false, "because": "Nicht Ziel"}, {"text": "Primzahlen bestimmen", "correct": false, "because": "Andere Methode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte umfasst der Euklidische Algorithmus?', 5, '[{"text": "Division mit Rest", "correct": true, "because": "Rest berechnen"}, {"text": "Wiederholung bis Rest 0", "correct": true, "because": "Iterativ"}, {"text": "Multiplikation", "correct": false, "because": "Nicht Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Euklidische Algorithmus basiert auf Division. b) Er funktioniert nur mit Primzahlen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Zahlen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Euklidischen Algorithmus?', 4, '[{"text": "Restwert", "correct": false, "because": "Kern der Berechnung"}, {"text": "Division", "correct": false, "because": "Grundschritt"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Euklidische Algorithmus rekursiv sein kann?', 2, '[{"text": "Ja", "correct": true, "because": "Rekursiv oder iterativ"}, {"text": "Nein", "correct": false, "because": "Rekursion möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche mathematische Eigenschaft nutzt der Euklidische Algorithmus?', 3, '[{"text": "GGT bleibt gleich bei Subtraktion", "correct": true, "because": "Restprinzip"}, {"text": "Primfaktorzerlegung", "correct": false, "because": "Andere Methode"}, {"text": "Multiplikation", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet der Euklidische Algorithmus?', 5, '[{"text": "Effizienz", "correct": true, "because": "Schnelle Berechnung"}, {"text": "Einfachheit", "correct": true, "because": "Wenige Schritte"}, {"text": "Hoher Speicherbedarf", "correct": false, "because": "Minimal"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Euklidische Algorithmus findet den GGT. b) Er ist nur für große Zahlen geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Zahlen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Euklidischen Algorithmus?', 4, '[{"text": "Zwei Zahlen", "correct": false, "because": "Eingabewerte"}, {"text": "Division", "correct": false, "because": "Grundoperation"}, {"text": "Papierdokumentation", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Euklidische Algorithmus immer iterativ?', 2, '[{"text": "Nein", "correct": true, "because": "Auch rekursiv"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eingaben benötigt der Euklidische Algorithmus?', 4, '[{"text": "Zwei ganze Zahlen", "correct": true, "because": "GGT-Berechnung"}, {"text": "Positive Zahlen", "correct": true, "because": "Standard"}, {"text": "Textdaten", "correct": false, "because": "Numerisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Euklidische Algorithmus nur für Primzahlen funktioniert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Zahlen"}, {"text": "Ja", "correct": false, "because": "Nicht beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Euklidischen Algorithmus?', 3, '[{"text": "Effizienz", "correct": true, "because": "Schnelle Schritte"}, {"text": "Farben", "correct": false, "because": "Irrelevant"}, {"text": "Speicherplatz", "correct": false, "because": "Minimal nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Euklidische Algorithmus nutzt Restdivision. b) Er ist nur für Gleitkommazahlen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ganze Zahlen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen hat der Euklidische Algorithmus?', 5, '[{"text": "Kryptographie", "correct": true, "because": "GGT für RSA"}, {"text": "Bruchkürzung", "correct": true, "because": "Teiler finden"}, {"text": "Textformatierung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Euklidischen Algorithmus unwichtig?', 3, '[{"text": "Restwert", "correct": false, "because": "Kernschritt"}, {"text": "Zahlenpaar", "correct": false, "because": "Eingabe"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann der Euklidische Algorithmus erweitert werden?', 3, '[{"text": "Ja", "correct": true, "because": "Erweiterter Algorithmus"}, {"text": "Nein", "correct": false, "because": "Für Koeffizienten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Euklidische Algorithmus logarithmische Laufzeit hat?', 2, '[{"text": "Ja", "correct": true, "because": "O(log n)"}, {"text": "Nein", "correct": false, "because": "Effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für den Euklidischen Algorithmus zentral?', 4, '[{"text": "Restdivision", "correct": true, "because": "Grundprinzip"}, {"text": "Multiplikation", "correct": false, "because": "Nicht genutzt"}, {"text": "Papierdokumente", "correct": false, "because": "Irrelevant"}]');
